import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAS: [CaseTemplate] = [overpassGraffiti, benefitsOverreport, receiptReturnScam, erScuffle, smallClaimsLie, dentistOfficeBreakin, garageBurglary, shotgunFromTruck, barGlassInjury, stalkerCoworker, repeatBarAssault, streetPillSale, parkingKnifeIntent, vanCocaine, firefighterBurned, scaldChildAbuse]

    static let overpassGraffiti = SmallCases.make(
        key: "story.overpassGraffiti",
        category: .property,
        headlines: ["Overpass Painted Over Night, City Public Works Cleans Up", "Camera Catches Hooded Figure With Spray Cans"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a city bridge, causing damage of $1,100, on {DATE}.",
        ages: 18...25,
        victim: true,
        summary: "A highway overpass was painted with large letters overnight on {DATE}. A traffic camera showed a hooded figure with spray cans at 2 a.m. Cans in {D}'s car matched the paint. {DL} says {D.he} was nearby painting a legal mural.",
        state: [E(.video, 2, "Traffic Camera", "A hooded figure paints the overpass at 2 a.m."), E(.physical, 3, "Spray Cans", "Cans matching the paint in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Legal Mural", "{DL} says {D.he} was painting a permitted mural nearby.")],
        role: "Public works supervisor",
        exam: [.direct("What damage did you find on the overpass?", "\"Large letters in spray paint across the whole span, visible to every driver below. It was done overnight, and our crew found it at the start of the shift.\""), .direct("What did the cleanup cost?", "\"About $1,100, including the pressure washing and the repainting of the concrete. That comes out of the public works budget.\""), .direct("What did the traffic camera show?", "\"At 2 a.m., a hooded figure with spray cans at the overpass. Later, cans in {D}'s car matched the paint on the wall.\""), .direct("What is your role with the city, and how did you learn about the paint?", "\"I supervise the public works crew. A driver called the non-emergency line at about six that morning, and I drove out to the overpass to see for myself.\""), .direct("Describe how large the painting was.", "\"Letters about four feet high running across the whole span, in black with a red outline. It covered the concrete face and part of the guardrail.\""), .direct("How did deputies connect {D} to it?", "\"They pulled the traffic camera for the overpass and saw a hooded figure with spray cans at 2 a.m. Later they found cans in {DL}'s car that matched the black and red.\""), .cross("{D} says there was a permitted mural, doesn't {D.he}?", "\"Yes, there was a permit for a mural, but it covered a different wall, about a mile away, and not this overpass.\""), .cross("Lots of people carry spray cans, don't they?", "\"Yes, many people do. Cans alone are not what I rely on. The matching color is part of it.\""), .cross("Can you identify the figure on camera?", "\"No. The hood hides the face, and the figure is small at that distance.\""), .cross("Does the traffic camera show a face or a license plate?", "\"No face. The figure is in a hood and is shown from the side, and the camera is pointed at traffic, so I can't tell you who it is.\""), .cross("Are those paint colors sold in every hardware store?", "\"Yes. Black and red are two of the most common colors we see, and I couldn't pick out a brand from the photos.\"")],
        theory: ("{D} painted a city bridge.", "A legal mural elsewhere."),
        allocution: "\"It was illegal. I'll clean it.\"",
        truths: ("The permit covered a wall a mile away.", "A traffic camera clock showed {DL}'s car at the permitted wall at the time."),
        defendant: [.direct("Did you paint the overpass?", "\"No. I did not paint that overpass. I was painting a legal mural that night, with a permit, at a different wall.\""), .direct("Where were you at 2 a.m.?", "\"At the permitted wall, working on the mural. I had my cans with me, and I was painting for a few hours.\""), .direct("Why are the cans in your car the same color?", "\"I used the same colors for the mural. They are common colors, and many painters buy them.\""), .direct("Describe the mural you were painting for the jury.", "\"I had a permit from the property owner for a wall about a mile from the overpass. I was working late because I had a day job and only had evenings.\""), .direct("How did you spend that night?", "\"From about midnight I worked on the wall, blocking in letters and colors. I took a short break around two for coffee and then went back.\""), .direct("Why were your cans in your car?", "\"I store my supplies in the back seat and carry them to wherever I'm painting. I had about twenty cans, mostly the same colors I was using.\""), .cross("The lettering on the overpass looks like your style, doesn't it?", "\"It is a style many people use. I would not say it is mine alone.\""), .cross("The permit was for a different wall. Why were you near the overpass?", "\"I was not at the overpass. I was a mile away, and I can show where I parked.\""), .cross("You carried spray cans at 2 a.m. How is that not suspicious?", "\"It looks odd, I know. But painters work at odd hours, and I had permission for that wall.\""), .cross("Your permit covered a wall a mile away. Isn't a mile a short drive from an overpass?", "\"It's a short drive, but I didn't make it. I stayed at the wall until I finished at about four.\""), .cross("The lettering on the overpass looks a lot like your style. Does it?", "\"It looks like a common style among writers in this area. I'm not the only person who paints that kind of lettering.\"")],
        openings: ("A highway overpass was covered in large spray-painted letters overnight. A traffic camera shows a hooded figure with cans at 2 a.m., and cans in {D}'s car match the paint on the wall.", "{D} was painting a permitted mural a mile away that night. The defense will show a different wall, a legal permit, and a traffic camera that places {D} somewhere else."),
        closings: ("A hooded figure at 2 a.m., spray cans in {D}'s car, and a style that matches. The permit covered a different wall, and the damage cost the town $1,100.", "A face hidden by a hood, common paint colors, and a permit for a mile-away wall. The State has not put {D} at that overpass, and that is where its case ends."),
        timeline: [(0, "1:40 a.m.: {DL} parks near the overpass."), (0, "2 a.m.: the painting."), (0, "6 a.m.: public works sees it.")],
        identified: "A traffic camera.",
        mood: .indifferent)

    static let benefitsOverreport = SmallCases.make(
        key: "story.benefitsOverreport",
        category: .whiteCollar,
        headlines: ["Mother Collected Food Assistance While Working Second Job, Agency Says", "Caseworker Finds Unreported Wages"],
        law: "falsePretenses",
        spec: "Obtained $3,400 in food assistance benefits from {V}, a county agency, by false pretenses, on {DATE}.",
        ages: 22...55,
        victim: true,
        summary: "A county agency found that {D} reported no income for eleven months while earning wages at a restaurant, resulting in $3,400 in benefits {D} should not have received. {DL} says a caseworker told {D.him} the wages did not need reporting. The agency says {D} earned about $1,400 a month and signed each renewal form stating no income, and its caseworker's notes show no such advice.",
        state: [E(.document, 3, "Payroll Records", "Eleven months of wages at a restaurant."), E(.document, 3, "Applications", "Signed forms stating no income.")],
        defense: [E(.statement, 1, "Caseworker Advice", "{DL} says a caseworker said the wages need not be reported.")],
        role: "Agency investigator",
        exam: [.direct("What did your investigation find?", "\"That {D} reported no income to the county for eleven months while earning wages at a restaurant. The overpayment was $3,400 in benefits.\""), .direct("How did you learn about the wages?", "\"We matched payroll records from the restaurant to the benefit file. They show regular paychecks across those eleven months.\""), .direct("How much did {D} earn?", "\"About $1,400 a month. That's well above the level that would have reduced or ended the benefits.\""), .direct("What forms did the defendant sign?", "\"Each renewal form, including the first one a month after starting work. They state no income, and {DL} signed under a warning about false statements.\""), .direct("What did the defendant say when you spoke?", "\"{D.He} said a caseworker told {D.him} the wages did not need to be reported. {D.He} could not name the caseworker.\""), .direct("What did the caseworker's notes show?", "\"Nothing. The file has no note of that advice, and notes are routinely recorded after each contact.\""), .cross("Isn't it true caseworkers sometimes give informal advice?", "\"It happens, and not every conversation is written down. That is one reason I asked the supervisor about it.\""), .cross("Did the defendant try to hide the job?", "\"I don't have evidence of an attempt to hide it. {D.He} worked under {D.his} real name and Social Security number.\""), .cross("Did you speak to the caseworker?", "\"I did, and the caseworker said they don't recall giving that advice. That isn't the same as saying it never happened.\""), .cross("Did the supervisor comment on this kind of advice?", "\"The supervisor said such advice had been given to other clients that year. I have a note of that conversation.\""), .cross("Did the defendant repay any of the overpayment?", "\"Not yet. {D.He} said {D.he} wanted to work out a plan once the matter was explained.\"")],
        theory: ("{D} hid wages to keep benefits.", "Advice from a caseworker."),
        allocution: "\"I should have reported. I'm sorry.\"",
        truths: ("No note of that advice exists in the file.", "A caseworker's supervisor confirmed advice of that kind had been given to other clients that year."),
        defendant: [.direct("Describe your job for the jury.", "\"I started waiting tables at a restaurant. The pay was small and the hours changed week to week, so some months were low.\""), .direct("Why didn't you report the income?", "\"I asked a caseworker, and the caseworker said the wages did not need to be reported. I accepted that answer and filed my forms the same way.\""), .direct("When did you speak to the caseworker?", "\"Soon after I started, at the office. I don't remember the exact date, but I remember what I was told.\""), .direct("Did you sign the forms?", "\"Yes. I signed each one, and I filled in no income because I believed the caseworker.\""), .direct("Did you use your real name at work?", "\"Of course. My payroll was under my real name and number. I wasn't hiding anything from anyone.\""), .direct("What do you want to say to the county?", "\"I'd pay back what I owe once someone explains it. I never meant to take anything I wasn't owed.\""), .cross("You signed forms saying no income eleven times, didn't you?", "\"Yes. I signed them without reading closely, because I believed what I was told.\""), .cross("You can't name the caseworker?", "\"No. I've seen a few different ones over the years, and I didn't write down a name.\""), .cross("You earned about $1,400 a month?", "\"Around that, give or take. It wasn't a huge amount, but I needed every dollar of the benefits too.\""), .cross("The forms warn about false statements, don't they?", "\"I think they do. I didn't read the fine print carefully, and that was a mistake.\""), .cross("You never asked anyone else about the rules?", "\"No. I trusted the first answer I got. I know I should have checked with someone else.\"")],
        openings: ("For eleven months {D} earned about $1,400 a month at a restaurant while signing renewal forms stating no income, collecting $3,400 in benefits {D} should not have received. The State will show the payroll records and the signed forms.", "{D} was told by a county caseworker that the wages did not need to be reported and trusted that advice. The defense says an honest reliance on official guidance is not fraud."),
        closings: ("Eleven months of payroll, eleven signed forms, and $3,400 in benefits. {D} signed no income while the paychecks arrived, and no note in the file records any advice.", "{D} worked openly under a real name, the supervisor confirmed that such advice was given to other clients, and {D} trusted the county's own caseworker. The State has not proved intent to deceive."),
        timeline: [(-330, "{DL} starts at the restaurant."), (-300, "The first signed form."), (0, "The agency finds the payroll records.")],
        identified: "Payroll and benefit records.",
        mood: .sympathetic,
        genders: ["D": .female])

    static let receiptReturnScam = SmallCases.make(
        key: "story.receiptReturnScam",
        category: .property,
        headlines: ["Shopper Returns Items Without Buying Them, Store Says", "Receipt Reuse Costs Retailer $640"],
        law: "larcenyMerchant",
        spec: "Obtained $640 in store credit from {V}, a retailer, by return fraud, on {DATE}.",
        ages: 20...55,
        victim: true,
        summary: "Over three weeks ending {DATE}, {D} returned seven items to an electronics store with receipts that did not match the purchases. A store audit found each receipt had already been used. {DL} says the items were gifts and {D.he} used the receipts given to {D.him}.",
        state: [E(.document, 3, "Return Log", "Seven returns using receipts already used."), E(.video, 2, "Return Counter Camera", "{D} at the counter on each date.")],
        defense: [E(.statement, 1, "Gifts", "{DL} says the items were gifts with receipts.")],
        role: "Store manager",
        exam: [.direct("What did your audit find?", "\"Over three weeks, {D} returned seven items with receipts that did not match the purchases. Every one of those receipts had already been used.\""), .direct("What was the total value?", "\"The returns came to about $640. We refunded or credited that amount before the audit caught up.\""), .direct("What did you notice about the items themselves?", "\"They had no store tags. Items bought in our store carry tags that are removed at checkout, and these did not look like they came from us.\""), .direct("How does your return policy work?", "\"A customer brings an item and the original receipt, and we match the receipt to the transaction in our system. If the item matches, we refund the original payment method.\""), .direct("What did you notice during the audit?", "\"Seven returns over three weeks by the same person, each with a receipt that had already been used once for a different return.\""), .direct("How did you review the camera footage?", "\"The return counter camera shows {DL} at the counter on all seven dates, always with a bag and a receipt. The dates match the return log.\""), .cross("{D} said these were gifts, didn't {D.he}?", "\"Yes. That was the explanation, and it is unusual to receive seven gifts in three weeks.\""), .cross("The receipts were handed over to the defendant, weren't they?", "\"So {DL} said. I did not see who handed them over, but {DL} presented them at the counter.\""), .cross("Did the defendant ever hide who {D.he} was at the return counter?", "\"No. {D.He} used a real ID each time, and I note that. It is not the usual pattern.\""), .cross("Did the defendant ever try to hide who {D.he} was?", "\"No. {DL} used a real ID each time and was polite. I have no evidence {DL} tried to disguise anything.\""), .cross("Could a gift giver have handed the defendant a stack of receipts?", "\"It's possible. I can only say the receipts did not match the items, and I don't know how {DL} came to have them.\"")],
        theory: ("{D} returned items with reused receipts.", "Gifts with receipts."),
        allocution: "\"I'm sorry.\"",
        truths: ("The items had no store tags.", "The gift giver confirmed giving {DL} seven items and their receipts."),
        defendant: [.direct("Did you buy those items?", "\"No. They were gifts from a friend. The friend gave me the items and the receipts and told me to return what I did not want.\""), .direct("Why did you return so many?", "\"They were different gifts over different weeks. I did not need them, so I took them back to the store.\""), .direct("Did you know the receipts had been used?", "\"No. I had no idea. I trusted that the receipts were good, because my friend handed them to me.\""), .direct("Tell the jury about the friend who gave you the items.", "\"A friend I've known for years bought several electronics as gifts and then decided they weren't needed. I was asked to return them and keep the credit.\""), .direct("How did you end up with the receipts?", "\"They were in the bags with the items. I assumed they were the right ones and handed each one over at the counter.\""), .direct("What did you do when the manager asked about the returns?", "\"I told the manager exactly where the items came from and offered to give the friend's name. I wasn't worried because I'd done nothing wrong.\""), .cross("Seven returns in three weeks. Wasn't that a lot?", "\"It was. I was getting items from a friend and I took them back as they came.\""), .cross("The items had no store tags. Didn't that tell you something?", "\"I did not look. I should have asked more questions, and I understand why that looks careless.\""), .cross("Can you name the friend?", "\"I can give a name. I know it is hard to rely on a name the jury has not met.\""), .cross("Seven returns in three weeks, all with used receipts. Didn't you wonder why?", "\"I did start to wonder by the fifth one. I should have asked more questions, and I'm embarrassed that I didn't.\""), .cross("You kept the credit from every return. Did you tell the friend?", "\"Yes. The friend said I could keep it as thanks, and that is why I kept doing it.\"")],
        openings: ("Over three weeks, {D} returned seven items to an electronics store with receipts that had already been used. The audit shows reused receipts, items with no store tags, and about $640 in refunds.", "By the end of this trial, the proof will show that {D} received gifts and receipts from a friend and returned them in good faith. A reused receipt is not proof that {D} knew."),
        closings: ("Seven returns, seven reused receipts, and no tags on any item. This is not a gift problem. This is a pattern, and the store was the one who paid.", "{D} used a real ID, a real name, and the receipts given. The gift giver confirmed the story. The State has not shown that {D} knew what the receipts were."),
        timeline: [(-21, "The first return."), (-7, "The audit begins."), (0, "The seventh return.")],
        identified: "The return log.",
        mood: .indifferent)

    static let erScuffle = SmallCases.make(
        key: "story.erScuffle",
        category: .publicOrder,
        headlines: ["Patient's Relative Struggles With Deputy at Hospital", "Resisting Charge After Emergency Room Argument"],
        law: "resisting",
        spec: "Resisted, delayed, and obstructed a public officer in discharging a duty of {D.his} office, on {DATE}.",
        ages: 20...60,
        victim: false,
        summary: "A deputy asked {D} to leave a hospital hallway on {DATE} after staff reported {D} shouting. {D} refused, pulled away when the deputy took {D.his} arm, and had to be walked out. {DL} says {D.he} was worried about a relative and did not hear the order.",
        state: [E(.statement, 3, "Deputy", "{D} refused to leave and pulled away."), E(.video, 2, "Hospital Camera", "{D} pulls away from a deputy.")],
        defense: [E(.statement, 1, "Worried", "{DL} says {D.he} was frantic about a relative.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to on {DATE}?", "\"Hospital staff asked me to remove {D} from a hallway at about 7:40 p.m. They reported that {DL} had been shouting and would not leave.\""), .direct("What did you see on arrival?", "\"I saw {DL} standing in the hallway outside the emergency department, upset and speaking loudly. A nurse and a security guard were nearby.\""), .direct("What did you say to {D}?", "\"I told {D.him} that staff wanted {D.him} to leave the hallway and wait in the lobby. I asked twice and explained why.\""), .direct("How did the defendant respond?", "\"{D.He} refused and said {D.he} needed to be there for a relative. When I took {D.his} arm, {D.he} pulled away.\""), .direct("What did you do then?", "\"I held on, and with the help of security I walked {DL} to the lobby. {DL} didn't strike anyone.\""), .direct("What does the hospital camera show?", "\"It shows {DL} pulling away from my grip in the hallway. It also shows the nurse speaking to {DL} earlier.\""), .cross("Isn't it true the defendant was frightened for a relative?", "\"Yes. {D.He} told me that. I could tell {D.he} was upset, and I didn't doubt it.\""), .cross("Did the defendant threaten or strike anyone?", "\"No. {D.He} was loud and pulled away, but I didn't see any punch or a threat.\""), .cross("Did the defendant seem to hear your order?", "\"{D.He} was distracted and talking over me. I can't say for sure whether every word registered.\""), .cross("How long did the entire contact last?", "\"About ten minutes from the time I arrived until {D.he} was in the lobby. It wasn't a long encounter.\""), .cross("Did {D} apologize?", "\"Yes, {D.he} apologized in the lobby. {D.He} was crying and said {D.he} was just worried.\"")],
        theory: ("{D} resisted a lawful order.", "A frantic relative."),
        allocution: "\"I'm sorry. I was scared.\"",
        truths: ("A nurse had asked {DL} to leave twice.", "The relative was in surgery."),
        defendant: [.direct("Why were you at the hospital?", "\"A relative had been brought in that evening in bad shape. I arrived around 7 and was trying to find out what was happening.\""), .direct("How were you feeling?", "\"Frantic. I didn't know whether my relative would survive, and nobody would tell me anything.\""), .direct("Did a nurse ask you to leave?", "\"I remember a nurse speaking to me, but I wasn't taking in the words. I was just trying to get information.\""), .direct("Did you hear the deputy's order?", "\"Not clearly. I heard a voice, and then a hand on my arm, and I jerked away. I didn't think about who it was.\""), .direct("What happened with your relative?", "\"They were in surgery. I found out an hour later and sat in the lobby waiting.\""), .direct("How do you feel about what happened?", "\"Embarrassed. I know I was loud, and I wish I'd stayed calm. I'd apologize to the staff.\""), .cross("You were asked more than once to leave?", "\"I'm told so. I wasn't listening, and I know that's no excuse.\""), .cross("You pulled away when the deputy took your arm?", "\"Yes. It was a reflex. I didn't push or strike, and I didn't intend to resist.\""), .cross("You kept shouting after the nurse spoke to you?", "\"I was raising my voice because I was desperate for answers. I understand it disrupted the hallway.\""), .cross("The hospital camera shows you pulling away?", "\"I'm sure it does. I'm not arguing with it.\""), .cross("You walked to the lobby after that?", "\"Yes. Once I understood who it was and what they wanted, I went along.\"")],
        openings: ("At a hospital on {DATE}, staff asked {D} to leave a hallway after shouting, and when a deputy took {D}'s arm, {D} pulled away and had to be walked out. The hospital camera captured the struggle.", "{D} was frantic about a relative in surgery and did not hear the orders. The defense says a reflex of fear is not resistance."),
        closings: ("A nurse asked {D} to leave, a deputy gave a lawful order, and {D} refused and pulled away. The hospital camera shows it, and a deputy had to walk {D} out.", "{D} was terrified for a relative who was in surgery and was not hearing anything. A flinch under that kind of stress is not willful resistance."),
        timeline: [(0, "7 p.m.: {DL}'s brother arrives in distress."), (0, "7:30 p.m.: staff ask {DL} to leave."), (0, "7:40 p.m.: a deputy takes {D.his} arm.")],
        identified: "A deputy and a hospital camera.",
        mood: .sympathetic)

    static let smallClaimsLie = SmallCases.make(
        key: "story.smallClaimsLie",
        category: .publicOrder,
        headlines: ["Landlord Charged With Lying Under Oath at Small Claims Hearing", "Court Records Contradict Sworn Statement"],
        law: "perjury",
        spec: "Willfully and knowingly made a false statement under oath in a judicial proceeding, on {DATE}.",
        ages: 30...70,
        victim: false,
        summary: "At a small claims hearing on {DATE}, {D}, a landlord, swore that {D.he} had returned a tenant's $1,200 deposit. A bank record showed no such payment. The magistrate referred the matter. {DL} says {D.he} misspoke and believed the refund had been mailed.",
        state: [E(.document, 3, "Transcript", "{D} swears the deposit was returned."), E(.document, 3, "Bank Records", "No refund payment in the account.")],
        defense: [E(.statement, 1, "Misspoke", "{DL} says {D.he} believed it was mailed.")],
        role: "Small claims clerk",
        exam: [.direct("What did {D} say under oath at the hearing?", "\"{D}, a landlord, swore that the tenant's $1,200 deposit had been returned. The magistrate asked directly, and {D.he} answered yes.\""), .direct("What do the records show?", "\"A bank record shows no such payment. There is no refund of the deposit on the account that month or after.\""), .direct("What happened next?", "\"The magistrate referred the matter for review after seeing the bank record. It is not typical, and it was done to protect the integrity of the hearing.\""), .direct("What is your role at the small claims court?", "\"I'm the clerk in the magistrate's office. I swear in witnesses, keep the record of the hearing, and schedule cases.\""), .direct("What is the process when a witness gives testimony that appears wrong?", "\"If the magistrate or a party raises an issue about the testimony, we flag it and the magistrate can refer it for review. Here the tenant's lawyer produced bank records.\""), .direct("What did the bank records show?", "\"They showed the deposit account stayed unchanged for months, with no $1,200 refund written. The tenant had also testified that no money came back.\""), .cross("{D} may have been mistaken, mightn't {D.he}?", "\"It is possible. I am not in a position to say what {D.he} believed. I can only say what was sworn and what the bank shows.\""), .cross("The statement was made under oath, wasn't it?", "\"Yes. {D.He} was sworn in before the testimony. That is how it works in our small claims courtroom.\""), .cross("Did you hear {D} say anything about mailing a check?", "\"I did not note that at the hearing. I only recorded the statement that it was returned.\""), .cross("Did the defendant correct the testimony at the hearing?", "\"No. {D.He} did not say anything after the records were shown, and the magistrate referred the matter for review.\""), .cross("Was the defendant represented by a lawyer?", "\"No. {D.He} came without a lawyer, as most landlords in small claims do, and spoke for {D.himself}.\"")],
        theory: ("{D} lied under oath.", "A mistaken belief."),
        allocution: "\"I should have checked.\"",
        truths: ("{DL} had been told by the tenant twice that no refund came.", "A check was written but never mailed."),
        defendant: [.direct("Did you lie under oath?", "\"No. I believed the refund had been sent. I would never knowingly say something false in court.\""), .direct("Why did you say the deposit was returned?", "\"I believed it had been mailed. I wrote a check and I thought it went out in the mail.\""), .direct("What do you think happened to the check?", "\"I do not know. I may have set it aside or it may not have been mailed. I did not check.\""), .direct("Describe the tenant and the deposit in your own words.", "\"The tenant moved out about two months before the hearing. We argued over some damage, and I decided to refund most of the $1,200.\""), .direct("What did you do to return the deposit?", "\"I wrote a check at my kitchen table and put it in an envelope. I thought I'd mailed it and then got busy with other things.\""), .direct("What did you think when the bank records were shown?", "\"I was shocked. I realized I might have left the envelope on the counter, and I went home and found it that night.\""), .cross("The tenant told you twice that no refund came, didn't they?", "\"They did. I did not listen carefully. I was busy and I assumed it would arrive.\""), .cross("You swore the money was returned. Did you verify before you swore?", "\"No. I own that. I did not check the bank record, and I regret that.\""), .cross("A check that was never mailed is a check that was never returned, isn't it?", "\"Yes. I see that now. But when I testified, I honestly believed it had been mailed.\""), .cross("The tenant told you twice that no refund came. Why didn't you check?", "\"I thought the tenant was upset about the damage and stalling. I should have looked at my own records before I said anything.\""), .cross("You swore under oath. Why not say you weren't sure?", "\"Because I believed I'd mailed it. I didn't have any doubt, and I was wrong.\"")],
        openings: ("At a small claims hearing, {D}, a landlord, swore that a tenant's $1,200 deposit had been returned. A bank record shows no such payment, and the magistrate referred the matter.", "The defense witnesses will explain that {D} believed a check had gone out in the mail. A mistaken statement is not perjury unless the State proves {D} knew it was false."),
        closings: ("{D} swore the deposit was returned, the bank record says otherwise, and the tenant had told {D} twice that nothing came. This was not a slip, it was a choice.", "A check that was written and never mailed is a mistake, not a lie. The State has to show {D} knew the statement was false, and a careless landlord is not a criminal."),
        timeline: [(-60, "The tenant moves out."), (-30, "{DL} writes a check and does not mail it."), (0, "{DL} swears at the hearing.")],
        identified: "A transcript and bank records.",
        mood: .indifferent,
        doctrines: ["mistakeOfFact"])

    static let dentistOfficeBreakin = SmallCases.make(
        key: "story.dentistOfficeBreakin",
        category: .property,
        headlines: ["Dental Office Broken Into After Hours, Drug Cabinet Emptied", "Alarm Company Logs Rear Door Forced at 3 a.m."],
        law: "feloniousBE",
        threshold: 6,
        spec: "Broke and entered a building of {V}, a dental office, with intent to commit larceny therein, on {DATE}.",
        ages: 20...50,
        victim: true,
        summary: "A dental office's rear door was forced at 3 a.m. on {DATE} and a locked cabinet of medications was emptied. An alarm company logged the break-in. A pry bar in {D}'s car had paint transfer matching the door. {DL} says the bar was for work and {D.he} was home.",
        state: [E(.forensic, 3, "Paint Transfer", "Paint on a pry bar in {D}'s car matches the rear door.", .search), E(.digital, 2, "Alarm Log", "Rear door forced at 3:04 a.m.")],
        defense: [E(.statement, 1, "Home", "{DL} says {D.he} was home asleep.")],
        role: "Dentist",
        exam: [.direct("What did you find at your office on {DATE}?", "\"When my staff arrived at 7:30 a.m., the rear door had been pried open. A locked medication cabinet inside had been emptied.\""), .direct("What had been in the cabinet?", "\"Controlled pain medications and sedatives that we keep for procedures. It was a locked metal cabinet inside a locked room.\""), .direct("What did the alarm company report?", "\"The rear door was forced at 3:04 a.m. and the cabinet was emptied by about 3:20. They logged every sensor.\""), .direct("What did you notice about the door?", "\"The frame was splintered and pry marks ran along the edge, with scrapes of paint. It looked like a pry bar had been used.\""), .direct("How did {D} become connected?", "\"A deputy found a pry bar in {D}'s car. Paint transfer on the bar matched the paint on our rear door.\""), .direct("What did it cost you?", "\"Replacing the door and cabinet, the lost medications, and a day of closed appointments. It was a significant loss.\""), .cross("Isn't it true you did not see who broke in?", "\"Correct. We were closed. I only know the alarm log and what we found in the morning.\""), .cross("How common is that paint color on doors?", "\"It's a standard commercial color used on a lot of doors around town. I can't say it's unique to ours.\""), .cross("Was there a prescription pad missing?", "\"Not from my office. Our pads were locked up and still there.\""), .cross("Did any camera show the break-in?", "\"No. We have the alarm log, but our camera system didn't cover the rear door.\""), .cross("Did you know the defendant?", "\"No. {D.He} was not a patient and had no connection to the office that I'm aware of.\"")],
        defenseRole: "Defendant's roommate",
        defenseExam: [.direct("How do you know {D}?", "\"{D} is my roommate. We share an apartment, and we've been living together for about a year.\""), .direct("What did you do the evening of the break-in?", "\"We were both home. We watched TV and ate, and {D.he} was still up when I went to bed before midnight.\""), .direct("Did you see the defendant in the apartment that night?", "\"Yes, until I fell asleep. {D.He} was on the couch when I went to my room.\""), .direct("What kind of work does the defendant do?", "\"Odd jobs, mostly demolition and repairs. {D.He} carries tools in the car, including a pry bar.\""), .direct("Have you ever seen the defendant take drugs?", "\"No. I've never seen {DF} use anything like that, and {DF} doesn't have that kind of habit.\""), .direct("What kind of person is the defendant?", "\"Reliable. {DF} pays the rent on time and keeps the place clean. I've never seen {DF} do anything illegal.\""), .cross("You were asleep before midnight, weren't you?", "\"Yes. I went to bed early and slept hard. I can't say what {D.he} did after that.\""), .cross("Did you hear {D} leave in the night?", "\"No, but I sleep with a fan on. I wouldn't necessarily have heard the door.\""), .cross("You didn't see the defendant at 3 a.m.?", "\"No. I can only speak to the evening, and I know that leaves a gap.\""), .cross("Do you know about a prescription pad in the defendant's car?", "\"I don't know anything about it. I never saw {D.him} with one.\""), .cross("You're friends with the defendant, aren't you?", "\"I am, but I'd tell the truth either way. I'm only saying what I know.\"")],
        theory: ("{D} pried a door and took drugs.", "A man at home asleep."),
        allocution: "\"I did it. I'm sorry.\"",
        truths: ("A prescription pad was in {DL}'s glove box.", "The roommate fell asleep before midnight."),
        defendant: [.direct("Where were you at 3 a.m. on {DATE}?", "\"At home asleep. I live with a roommate, and I went to bed that night around midnight.\""), .direct("Why did you have a pry bar in your car?", "\"For work. I do odd jobs and carry tools, and a pry bar is a basic one I use for demolition.\""), .direct("How did paint get on it?", "\"I've used it on lots of doors and frames over the years. A matching paint isn't strange to me.\""), .direct("Have you been to that dental office?", "\"Never. I've never been a patient, and I couldn't tell you where the back door is.\""), .direct("Did you take any medications from that cabinet?", "\"No. I wouldn't know how to get into one, and I don't use those kinds of drugs.\""), .direct("What did you do when deputies spoke to you?", "\"I told them where I was and offered to show the pry bar. I didn't have any reason to hide it.\""), .cross("A prescription pad was in your glove box, wasn't it?", "\"Yes, there was a pad. It isn't mine, and I can't say how it ended up there.\""), .cross("The paint on your pry bar matches the door?", "\"I'm told so. It's a common color, and I wouldn't be shocked if it matched many doors.\""), .cross("Your roommate can't say where you were at 3 a.m.?", "\"My roommate was asleep, too. We were both in bed, and neither of us was watching the clock.\""), .cross("You carry the pry bar in your car all the time?", "\"Yes. It's a tool I use for work, and I don't think about it.\""), .cross("You do odd jobs that bring you near buildings after hours?", "\"Rarely. Most of my work is during the day, and I wasn't working that night.\"")],
        openings: ("At 3:04 a.m. the rear door of a dental office was forced, and a locked cabinet of controlled medications was emptied. A pry bar in {D}'s car carried paint matching the door, and a prescription pad was in the glove box.", "{D} was home asleep, uses that pry bar in an odd-job business, and has never been to the office. The defense says common paint on a common tool does not place {D} at that door."),
        closings: ("The alarm shows a forced door at 3:04, the paint on {D}'s pry bar matches that door, and a prescription pad sat in {D}'s glove box. Each of those facts points to {D}.", "The paint is a standard color, the pry bar is a work tool, and a roommate says {D} was home that night. The State has not shown who stood at that rear door."),
        timeline: [(0, "3:04 a.m.: the rear door is forced."), (0, "3:20 a.m.: the cabinet is emptied."), (0, "7:30 a.m.: staff find the door pried.")],
        identified: "Alarm logs and paint transfer.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        genders: ["D": .male])

    static let garageBurglary = SmallCases.make(
        key: "story.garageBurglary",
        category: .property,
        headlines: ["Garage Burglary While Family Was at Church", "Doorbell Camera Shows Man Carrying Tool Chest"],
        law: "burglary2",
        threshold: 6,
        spec: "Broke and entered the dwelling of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "While {V}'s family was at church on {DATE}, a man opened a garage door, entered the house through the connecting door, and left with a tool chest and a television. A doorbell camera showed him. {D} was seen loading a television into a car matching the description. {DL} says {D.he} bought the television at a yard sale.",
        state: [E(.video, 3, "Doorbell Camera", "A man carries a tool chest from the garage."), E(.physical, 3, "Television", "{V}'s television, recovered from {D}'s trunk.", .search)],
        defense: [E(.statement, 1, "Yard Sale", "{DL} says {D.he} bought the television at a yard sale.")],
        role: "Homeowner",
        exam: [.direct("What happened while your family was out on {DATE}?", "\"We left for church around 10 a.m. When we got home, the garage door was open, a tool chest was gone, and so was our television.\""), .direct("How did the intruder get in?", "\"The garage door was opened, and the connecting door into the house was used. Nothing was broken, which made us think it was opened somehow.\""), .direct("What did the doorbell camera show?", "\"At 10:40 a.m. a person opens the garage door and carries a tool chest from the garage. At 11:15 the same person leaves with the television.\""), .direct("What did you lose?", "\"A tool chest full of tools I'd built up over twenty years and a flat-screen television. It was a big loss for our family.\""), .direct("How was {D} identified?", "\"A neighbor reported someone loading a television into a car matching the description. A deputy stopped {D}'s car and found my television in the trunk.\""), .direct("Was the television yours?", "\"Yes. I recognized the model and a scratch on the corner. It was undamaged, and I took it home.\""), .cross("Isn't it true you can't see the intruder's face clearly?", "\"The camera shows a figure, and it's not clear enough for me to name anyone. It's a side view and a cap.\""), .cross("Was the tool chest recovered?", "\"No. Only the television was recovered, and the tool chest is still missing.\""), .cross("Did the defendant know your family?", "\"Not as far as I know. I have no idea who {DL} is, and I'd never seen {DL} before.\""), .cross("Did your family tell anyone you'd be at church?", "\"We go every Sunday, so anyone who knew our schedule could have known. I don't know who might have.\""), .cross("How can you be sure the television was yours?", "\"I know the model and a scratch on the corner, and my receipt shows the serial number. It's mine.\"")],
        theory: ("{D} entered a home and took a television.", "A yard sale purchase."),
        allocution: "\"I took them. I'm sorry.\"",
        truths: ("{DL}'s phone was near the house.", "No yard sale was held that weekend."),
        defendant: [.direct("Where did you get the television?", "\"From a yard sale. I saw a sign on a corner that morning, stopped, and paid cash for it.\""), .direct("Where was the yard sale?", "\"A few streets away from the neighborhood, in someone's driveway. I couldn't give you the address, but I remember the sign.\""), .direct("Why was it in your trunk?", "\"I'd bought it that morning and was taking it home. I put it in the trunk because it was too big for the back seat.\""), .direct("Did you go to {V}'s house?", "\"No. I've never been to that house and I don't know the family. I was just driving around that morning.\""), .direct("What did you tell the deputy?", "\"That I'd bought the television at a yard sale. I showed the deputy the receipt I had, which was a note on a scrap.\""), .direct("Were you near that neighborhood that day?", "\"I live nearby, so I'm around often. I went by a few streets at various times, but I wasn't in that garage.\""), .cross("Your phone was near {V}'s house that morning, wasn't it?", "\"I'm told that. I live close, and my phone goes where I go. It doesn't mean I was inside.\""), .cross("You can't name the yard sale or the seller?", "\"No. I didn't get a name, and I didn't think I'd need it. I know that's not helpful.\""), .cross("There wasn't a yard sale that weekend, was there?", "\"I've been told that. I know what I saw, and I'm sure there was a sign, but I can't find it now.\""), .cross("You paid cash for a flat-screen from a stranger?", "\"Yes. It was a good price, and I took it. I don't think I'd have bought it if I thought it was stolen.\""), .cross("You were loading a television into a car matching the description?", "\"I was loading my television. My car is the same model as many others around town.\"")],
        openings: ("While {V}'s family was at church on {DATE}, someone opened the garage door, entered the house, and left with a tool chest and a television. A doorbell camera recorded the figure, and a deputy found {V}'s television in {D}'s trunk.", "{D} says the television was bought for cash at a yard sale, and {D} never went inside that house. The defense says a camera that shows no face and a purchase from a stranger do not prove a burglary."),
        closings: ("The doorbell camera shows the theft, the television turned up in {D}'s trunk, and {D}'s phone was near the house. The yard sale story has no address, no seller, and no weekend sale that matches.", "The camera never shows a face, the tool chest was not found, and {D} showed the deputy the television in the open. A bad purchase from a stranger is not a burglary."),
        timeline: [(0, "10 a.m.: the family leaves for church."), (0, "10:40 a.m.: the garage door opens."), (0, "11:15 a.m.: the man leaves with the television.")],
        identified: "A doorbell camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "Strangers in our house.",
        genders: ["D": .male])

    static let shotgunFromTruck = SmallCases.make(
        key: "story.shotgunFromTruck",
        category: .property,
        headlines: ["Shotgun Stolen From Unlocked Truck, Later Found in Pawn Shop", "Serial Number Leads Detective to Defendant"],
        law: "larcenyFirearm",
        threshold: 6,
        spec: "Stole a shotgun belonging to {V}, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "{V}'s shotgun was taken from the cab of an unlocked truck overnight on {DATE}. Two days later a pawn shop took in a shotgun from {D}. The serial number matched {V}'s records. {DL} says {D.he} bought it from a man at a gas station.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on a ticket for the shotgun."), E(.document, 3, "Serial Number", "Matches {V}'s purchase record.")],
        defense: [E(.statement, 1, "Gas Station", "{DL} says {D.he} bought it from a man at a gas station.")],
        role: "Gun owner",
        exam: [.direct("What was taken from your truck?", "\"My shotgun was taken from the cab overnight. The truck was unlocked, and I did not notice until the next morning.\""), .direct("How do you know it was yours when it turned up?", "\"The serial number matched my records. I keep the number written down, and I gave it to deputies.\""), .direct("What did deputies tell you about where it was found?", "\"Two days later, a pawn shop took in a shotgun from {D}. The number on that gun is the number on mine.\""), .direct("How do you store your shotgun, and when did you last see it?", "\"In the cab of my truck behind the seat, on hunting days. I saw it the evening before, when I parked in my driveway and went inside for the night.\""), .direct("How did you find out it was gone?", "\"The next morning I opened the truck door and the seat was pushed back. The shotgun and a box of shells were gone, so I called deputies.\""), .direct("How did it come back to you?", "\"A deputy called two days later and said a pawn shop took in a shotgun with my serial number. I identified it from my purchase record and a scratch on the stock.\""), .cross("The truck was unlocked, wasn't it?", "\"Yes. I know I should have locked it. It does not change the fact that the gun is mine.\""), .cross("{D} used {D.his} own ID at the pawn shop, didn't {D.he}?", "\"Yes. That is what I was told, and it is not what I would expect from a thief.\""), .cross("Did anyone see the defendant at your truck?", "\"No. I have no witness who saw {DL} near the truck, and no video.\""), .cross("Was the truck door locked?", "\"No. It was a bad habit and I know it. The truck has no alarm either.\""), .cross("Did you see anyone near your truck that night?", "\"No. My house is on a quiet street and I didn't hear or see anyone.\"")],
        theory: ("{D} stole and pawned a shotgun.", "A purchase at a gas station."),
        allocution: "\"I took it. I'm sorry.\"",
        truths: ("{DL} lived two doors down from {V}.", "The gas station camera showed no such sale."),
        defendant: [.direct("Did you take {V}'s shotgun?", "\"No. I did not touch {V}'s truck and I did not take anything out of it.\""), .direct("Where did you get the shotgun you pawned?", "\"I bought it from someone at a gas station. I paid cash, and I did not think much about it.\""), .direct("Why did you use your own ID?", "\"Because I had nothing to hide. I thought I had bought it honestly and I was selling it for some money.\""), .direct("Where did you buy the shotgun you pawned?", "\"At a gas station on the highway. Someone was selling it out of a truck, and I was short on cash for rent.\""), .direct("How much did you pay, and how did you decide to buy it?", "\"Two hundred dollars cash. I thought I could sell it for more, and I told myself it was a good deal.\""), .direct("Why did you take it to a pawn shop in your own name?", "\"Because I thought I was doing something legal. I gave my real ID and answered every question the clerk asked.\""), .cross("You live two doors down from {V}, don't you?", "\"Yes. It is a small street. I know what that looks like, but I did not take that gun.\""), .cross("A gun with a serial number that matched. You didn't check it?", "\"I did not check. I know I should have. I'm sorry it came to this.\""), .cross("You live two doors from {V}. Did you know {V} owned a shotgun?", "\"I knew {V} hunted. I never knew what guns {V} owned or where they were kept.\""), .cross("Can you describe the person who sold it to you?", "\"Not well. It was a quick conversation in a parking lot and I didn't pay close attention.\""), .cross("You never checked the serial number before you pawned it, did you?", "\"No. I assumed a gun from a seller at a gas station would be fine. In hindsight, checking that number would have been the obvious step.\""), .cross("A gas station camera showed no such sale, didn't it?", "\"That is what deputies told me. I believed I was at that station, but I cannot point to a video, and I understand why that counts against me.\"")],
        openings: ("A shotgun was taken from an unlocked truck overnight. Two days later, a pawn shop took in a shotgun from {D}, a neighbor two doors down, and the serial number matched.", "{D} bought a shotgun at a gas station and pawned it openly under {D.his} own name. The defense will show that nothing ties {D} to that truck."),
        closings: ("Same serial number, two days later, a neighbor two doors down. {D} says a gas station, but there is no seller and no video, and the gun came from {V}'s truck.", "Nobody saw {D} at that truck, and {D} used a real ID at the pawn shop. A person who buys a gun and sells it openly is not behaving like a thief."),
        timeline: [(0, "Overnight: the truck is entered."), (2, "{DL} pawns the shotgun."), (4, "{V} sees the pawn listing.")],
        identified: "A pawn ticket and serial number.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction)

    static let barGlassInjury = SmallCases.make(
        key: "story.barGlassInjury",
        category: .violent,
        headlines: ["Man Struck With Beer Mug at Bar, Needs Surgery", "Bartender Says Fight Started Over Seat"],
        law: "aisi",
        threshold: 7,
        spec: "Assaulted {V} inflicting serious injury, on {DATE}.",
        ages: 21...45,
        victim: true,
        summary: "A fight at a bar on {DATE} ended with {V} struck in the face with a beer mug. {V} needed surgery for a broken cheekbone. The bartender said {D} swung the mug. {DL} says {V} threw the first punch.",
        state: [E(.statement, 3, "Bartender", "{D} swung a mug at {V}'s face."), E(.forensic, 2, "Medical Records", "A fractured cheekbone requiring surgery.")],
        defense: [E(.statement, 1, "First Punch", "{DL} says {V} punched first.")],
        role: "Sheriff's deputy",
        exam: [.direct("What call brought you to the bar on {DATE}?", "\"Dispatch sent me at about 11:20 p.m. to a fight with injuries. When I arrived, {V} was on the floor with a bleeding face.\""), .direct("What was {V}'s condition?", "\"{V} had a deep gash and obvious swelling on the cheek. Paramedics took {V} to the hospital, where a fractured cheekbone required surgery.\""), .direct("What did the bartender tell you?", "\"That {D} swung a beer mug at {V}'s face after an argument over a seat. The bartender was ten feet away and saw it.\""), .direct("What was the sequence of events?", "\"The argument started around 11, a punch was thrown at 11:10, and the mug was swung at 11:11. Deputies arrived at 11:40.\""), .direct("What did {D} say?", "\"{DL} said {V} punched first and that {DL} was responding. {DL} said {D.he} didn't mean to hurt {V} that badly.\""), .direct("What did you find at the scene?", "\"A broken mug on the floor near the bar and blood on the floor. We collected the pieces and took photographs.\""), .cross("Isn't it true you did not see the first punch?", "\"I didn't. I arrived after it was over, and I was relying on the bartender and the witnesses.\""), .cross("Did the defendant have any marks from a punch?", "\"I didn't see any. {D.He} had no visible injury when I looked at {D.his} face.\""), .cross("Did anyone besides the bartender see the mug swing?", "\"A few patrons were nearby, but their accounts differed. The bartender's was the clearest.\""), .cross("Was the defendant intoxicated?", "\"I smelled alcohol, as I did on most people in the bar. {D.He} was steady and answered my questions.\""), .cross("Did the defendant try to leave before deputies arrived?", "\"No. {D.He} stayed at the bar until I arrived and made no attempt to run.\"")],
        defenseRole: "Defendant's friend",
        defenseExam: [.direct("How do you know {D}?", "\"{D} is a friend of mine. We were at the bar together that night, and we'd been there for a couple of hours.\""), .direct("What happened over the seat?", "\"{V} said the seat was taken and got in {DF}'s face. It escalated quickly, with a lot of pointing and raised voices.\""), .direct("What did you see {V} do?", "\"{V} swung at {DF}. I saw the punch come at {DF}'s face, and {DF} had to lean back.\""), .direct("What did the defendant do?", "\"{D.He} stood there for a second and then things went fast. I was turning to get my jacket and head out.\""), .direct("Why did you leave?", "\"I didn't want any part of a fight. I'd seen enough, and I figured {DF} would follow me out.\""), .direct("How would you describe the defendant's temper?", "\"Calm, usually. I've never seen {DF} start a fight, and I was surprised at how fast it escalated.\""), .cross("You left before the mug was swung, didn't you?", "\"Yes. I was already walking toward the door and didn't see the mug.\""), .cross("You didn't see the defendant get hit, did you?", "\"I saw {V} swing. I can't say whether the punch landed or grazed {DF}.\""), .cross("You can't say what happened in those last seconds?", "\"No. I only know what I saw up to the point I turned away.\""), .cross("You've known the defendant a long time, haven't you?", "\"Yes, for years. I'm trying to stay fair about what I saw.\""), .cross("The fight lasted about a minute?", "\"From the first punch to the mug was about a minute. It went very fast.\"")],
        theory: ("{D} hit {V} with a mug.", "A response to a punch."),
        allocution: "\"I'm sorry for the damage.\"",
        truths: ("{DL} had no mark from a punch.", "The friend left before the mug swing."),
        defendant: [.direct("How did the fight start?", "\"We argued over a seat at the bar. {V} said it was theirs and I said it was empty, and it got heated.\""), .direct("What did {V} do?", "\"{V} threw a punch at me. I stepped back and I swung the mug I was holding without thinking.\""), .direct("Did you mean to hit {V} in the face?", "\"No. I meant to keep {V} away. I didn't think about the mug being a weapon until it connected.\""), .direct("What did you do afterward?", "\"I stood there stunned. I called out for help and stayed until the deputies came. I wasn't going to leave.\""), .direct("Did you get hit?", "\"I felt the punch graze me. It wasn't enough to leave a mark, but it was real.\""), .direct("How has this affected you?", "\"Terrible. {V} needed surgery, and I never intended anything like that. I'd pay for it.\""), .cross("The bartender saw you swing the mug, correct?", "\"Yes, the bartender saw it happen. I don't deny that I swung it.\""), .cross("You had no mark from any punch?", "\"No visible mark. It grazed me, and I was more scared than hurt.\""), .cross("You swung a glass at someone's face?", "\"I swung it in the heat of the moment. I know how that sounds, and I regret it deeply.\""), .cross("You could have walked away from the argument?", "\"I could have. I'd been drinking and I let it get to me.\""), .cross("{V} suffered a fractured cheekbone?", "\"Yes. I'm told it required surgery. I'm sorry for that.\"")],
        openings: ("A fight over a seat at a bar ended with {V} struck in the face by a beer mug, a fractured cheekbone, and surgery. The bartender, ten feet away, saw {D} swing the mug.", "{V} threw the first punch, and {D} reacted in a split second in a crowded bar. The defense says the State has to prove {D} did not act in self-defense."),
        closings: ("A seat, an argument, a mug, and a fractured cheekbone. {D} swung a glass at {V}'s face, the bartender saw it, and the medical records show the result.", "{V} punched first, a friend saw the swing, and {D} reacted in a second. The State has not proved that {D}'s response was anything but self-defense."),
        timeline: [(0, "11 p.m.: the argument over a seat."), (0, "11:10 p.m.: the punch."), (0, "11:11 p.m.: the mug."), (0, "11:40 p.m.: deputies arrive.")],
        identified: "A bartender.",
        aggravating: ["The offense involved a victim who suffered serious injury"],
        mood: .divided,
        doctrines: ["selfDefense"],
        genders: ["V": .male])

    static let stalkerCoworker = SmallCases.make(
        key: "story.stalkerCoworker",
        category: .family,
        headlines: ["Coworker Says Colleague Followed Her Home for Months", "Photos on Phone Show Daily Surveillance"],
        law: "stalking",
        threshold: 6,
        spec: "Willfully harassed {V} on more than one occasion without legal purpose, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "Over four months ending {DATE}, {V} saw {D}, a coworker, outside {V.his} home, at a gym, and at a grocery store. {V} had asked {D} to stop. Photos on {D}'s phone showed {V}'s car and doorway. {DL} says the places were coincidences.",
        state: [E(.digital, 3, "Phone Photos", "Photos of {V}'s car and doorway taken from a distance."), E(.document, 2, "Incident Log", "{V}'s log of 14 sightings.")],
        defense: [E(.statement, 1, "Coincidence", "{DL} says the locations were coincidences.")],
        role: "Victim",
        exam: [.direct("Where did you see {D} over those four months?", "\"Outside my home, at my gym, and at the grocery store. It happened over and over, and I started to keep track.\""), .direct("Did you ask the defendant to stop?", "\"Twice. I said it clearly. After that, I kept seeing {D} in the same places.\""), .direct("What did you learn from the defendant's phone?", "\"There were photos of my car and of my doorway on {D.his} phone. I never gave permission for any of them.\""), .direct("When did you first notice the defendant outside your home?", "\"About four months ago. {D.He} was standing by a car across the street from my building one evening, and I didn't think much of it until I saw {D.him} again a week later.\""), .direct("What did you say to the defendant when you asked {D.him} to stop?", "\"I told {D.him} at work that I was uncomfortable and that {D.he} should stop showing up where I was. I said it again a few weeks later in an email.\""), .direct("How did you keep track of the sightings?", "\"I started a log on my phone with the date, time, and place. By the time I called deputies there were fourteen entries.\""), .cross("{D} lives nearby, doesn't {D.he}?", "\"No. {D.He} lives across town, so it does not fit that we would run into each other near my home.\""), .cross("{D} never threatened you, did {D.he}?", "\"No. There was never a threat. It was the repeated presence that scared me.\""), .cross("Isn't the gym a public place?", "\"Yes. Anyone can go to it. But it was the same gym, at my times, again and again.\""), .cross("Do you and the defendant work in the same department?", "\"No. We're in the same building but different departments, and I only see {D.him} in the elevator or the cafeteria.\""), .cross("Did the defendant ever speak to you or approach you outside work?", "\"Once at the grocery store, {DL} said hello and I walked away. Other times {DL} only appeared nearby.\"")],
        theory: ("{D} followed a coworker.", "Coincidences."),
        allocution: "\"I couldn't stop. I'm sorry.\"",
        truths: ("{DL} drove 20 minutes out of the way past {V}'s home each day.", "{DL}'s gym was assigned by an employer wellness plan that listed one gym for all staff."),
        defendant: [.direct("Did you follow {V}?", "\"No. I did not follow {V.him}. I ran into {V.him} in places we both go, and I did not think it was a problem.\""), .direct("Why were there photos of {V}'s car and doorway?", "\"They were scenery. I take pictures of the neighborhood and the street, and I did not mean them as anything.\""), .direct("Why were you near {V}'s home?", "\"It was on my way. I did not think of it as following. I used a route that happened to go past.\""), .direct("How well do you know {V}?", "\"We work in the same building and have said hello in the hall. I never had a conversation with {V.him} beyond that.\""), .direct("Tell the jury how the photos came to be on your phone.", "\"I like to take photographs of cars and neighborhoods. A couple of them included {V}'s car because it was parked on a street I walk through.\""), .direct("How did you react when {V} asked you to stop?", "\"I was surprised. I didn't think I'd done anything wrong, and I tried to stay out of {V.his} way after that.\""), .cross("Fourteen sightings. Is that a coincidence?", "\"It seems a lot. But I did not plan any of them. It sounds bad, I know.\""), .cross("You were asked to stop. Did you?", "\"I thought I had. I tried to avoid the places, but we kept running into each other.\""), .cross("The gym is the same one {V} attends. Why choose that gym?", "\"It is the one my workplace lists. I did not choose it because of {V}.\""), .cross("Fourteen sightings in four months. How is that coincidence?", "\"I live in the same part of town, shop at the same stores, and go to the same gym because of a work benefit. It adds up.\""), .cross("You kept taking photographs after {V} asked you to stop. Why?", "\"Because I thought the photos were harmless scenery. I should have stopped completely, and I understand now how it looked.\"")],
        openings: ("For four months, {V} saw {D}, a coworker, outside {V.his} home, at a gym, and at the grocery store, after asking {D} to stop. Photos on {D}'s phone showed {V}'s car and doorway.", "The defense evidence will establish that {D} lives and works in the same community, that the gym is public, and that the photos show scenery, not a plan to follow anyone."),
        closings: ("Fourteen sightings, two requests to stop, and photos of {V}'s car and doorway on {D}'s phone. Coincidence does not explain a pattern like this one.", "A public gym, a shared workplace, and photos of scenery. The State is asking you to turn coincidences into stalking, and it has not shown that {D} meant to follow anyone."),
        timeline: [(-120, "{V} first sees {DL} outside the home."), (-60, "{V} asks {DL} to stop."), (0, "{V} reports to deputies.")],
        identified: "A log and phone photos.",
        mood: .wantsConviction,
        impact: "I look behind me everywhere.",
        genders: ["V": .female])

    static let repeatBarAssault = SmallCases.make(
        key: "story.repeatBarAssault",
        category: .violent,
        headlines: ["Man With Prior Assault Convictions Charged Again After Parking Lot Fight", "Habitual Misdemeanor Assault Charge"],
        law: "habitualMisdAssault",
        threshold: 6,
        spec: "Assaulted {V}, having at least two prior assault convictions, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "{D} punched {V} in a bar parking lot on {DATE} after an argument over a parking space. {V} had a split lip. {D} has two prior assault convictions. {DL} says {V} threatened {D.him} first.",
        state: [E(.statement, 3, "Victim", "{D} punched {V} in the face."), E(.document, 3, "Prior Convictions", "Two prior assault convictions.")],
        defense: [E(.statement, 1, "Threat", "{DL} says {V} threatened {D.him} first.")],
        role: "Victim",
        exam: [.direct("What happened in the bar parking lot?", "\"{D} and I argued over a parking space. Then {D.he} punched me in the face, and I fell back with a split lip.\""), .direct("What injury did you have?", "\"A split lip that bled a lot and swelled up. I had it looked at, and it took a week to heal.\""), .direct("Had you spoken to {D} before?", "\"No. It was only the argument over the space. I did not know {D.him}.\""), .direct("What were you doing at the bar that evening?", "\"I'd gone with two coworkers after work for dinner and a couple of beers. We were leaving at about eleven when I pulled into the lot to move my car closer.\""), .direct("How did the argument about the space begin?", "\"I was backing into a spot and {D.he} pulled in behind me and honked. We both got out of our cars and exchanged words about who had the space first.\""), .direct("What did the defendant do right before the punch?", "\"{D.He} stepped up close to me with a clenched fist and said something I couldn't make out. Then {D.he} swung and hit me in the mouth.\""), .cross("You threatened the defendant first, didn't you?", "\"I shouted. I raised my voice, but I never moved toward {DL}, and I did not threaten to hurt anyone.\""), .cross("Was it only a parking space?", "\"Yes. It was just a parking space, and that is what makes this so senseless.\""), .cross("Had you been drinking?", "\"I had a couple of drinks at the bar. I was not drunk, and I knew what I was doing.\""), .cross("Did you say anything threatening to the defendant before the punch?", "\"I raised my voice and told {D.him} to move the car. I didn't say I would hurt {D.him}, and I didn't move toward {D.him}.\""), .cross("How much had you had to drink?", "\"Two beers over about two hours. I wasn't drunk and I wasn't unsteady, and I walked out of the bar on my own.\"")],
        theory: ("{D} punched a stranger again.", "A threatened man."),
        allocution: "\"I lost my temper again.\"",
        truths: ("A security camera showed {DL} swing first.", "{V} had shouted but never moved toward {DL}."),
        defendant: [.direct("Did you punch {V}?", "\"Yes, I hit {V.him}. But I did it after {V} threatened me, and I was afraid.\""), .direct("What about your past record?", "\"It is old. I have two prior convictions, and I have tried to stay out of trouble since.\""), .direct("What did you do when you pulled into the lot?", "\"I was looking for a space and found one that a car was backing into. I honked once to let the driver know I was waiting.\""), .direct("What did {V} say to you?", "\"{V} came toward me and said something like I'd regret parking there. I took it as a threat and I felt trapped between the cars.\""), .direct("What happened when you swung?", "\"I hit {V.him} once in the face. I was afraid {V.he} was about to hit me first, and I reacted.\""), .direct("What was going through your mind when {V} shouted at you?", "\"I was angry about the parking space and tired of being talked down to. I took the shout as a threat, but I did not stop to think before I swung.\""), .cross("The security camera shows you swinging first, doesn't it?", "\"The angle makes it look that way. I was reacting to what was said, and the camera does not have sound.\""), .cross("You have two prior assault convictions, don't you?", "\"Yes. I know that does not help me, but I am not the person I was then.\""), .cross("{V} had a split lip. Isn't that out of proportion to a shout?", "\"Yes, I feel that now. I did not mean to hurt {V.him} that badly.\""), .cross("You have two prior assault convictions. Isn't it true you were quick to use your fists again?", "\"I know that looks bad. I've been trying to stay out of trouble, and that night I felt cornered.\""), .cross("The camera shows you swinging before {V} touched you. Isn't that a fact?", "\"It shows me swing first, yes. It doesn't show what I heard or why I thought I had to.\"")],
        openings: ("After an argument over a parking space outside a bar, {D} punched {V} in the face, leaving a split lip. A security camera recorded it, and {D} has two prior assault convictions.", "By the end of this trial, the proof will show that {V} threatened {D} first and that {D} reacted out of fear. A camera without sound does not show what was said."),
        closings: ("A parking space, a shout, and a punch to the face. The camera shows {D} swinging first, and no shout justifies that.", "{V} threatened {D}, and a camera without sound cannot capture that. A person who throws one punch out of fear is not the same as an aggressor."),
        timeline: [(0, "11 p.m.: the parking-space argument."), (0, "11:05 p.m.: the punch."), (0, "11:30 p.m.: deputies arrive.")],
        identified: "A security camera.",
        aggravating: ["The offense involved a victim who suffered serious injury"],
        mood: .indifferent,
        genders: ["D": .male])

    static let streetPillSale = SmallCases.make(
        key: "story.streetPillSale",
        category: .drugs,
        headlines: ["Undercover Officer Buys Oxycodone on Street Corner", "Marked Bills Found in Seller's Pocket"],
        law: "saleSchedII",
        threshold: 6,
        spec: "Sold a Schedule II controlled substance, oxycodone, on {DATE}.",
        ages: 20...50,
        victim: false,
        summary: "An undercover officer bought three oxycodone pills for $60 from {D} on a street corner on {DATE}. Marked bills were found in {D}'s pocket minutes later. {DL} says {D.he} was selling a friend's pills at cost and did not know what they were.",
        state: [E(.video, 3, "Undercover Recording", "{D} hands over three pills for $60."), E(.physical, 3, "Marked Bills", "The $60 in marked bills found in {D}'s pocket.", .search)],
        defense: [E(.statement, 1, "Friend's Pills", "{DL} says the pills belonged to a friend.")],
        role: "Undercover officer",
        exam: [.direct("What did you buy from {D}?", "\"Three oxycodone pills for $60 on a street corner. I was working undercover, and the exchange was quick.\""), .direct("Where were the marked bills afterward?", "\"In {D}'s pocket, minutes later. Our team detained {D.him} and recovered the bills we had used.\""), .direct("What did you find on the defendant otherwise?", "\"Fourteen more pills hidden in a sock. They were the same kind of pill.\""), .direct("How was the buy arranged, and where did it happen?", "\"I approached {D.him} on a street corner and asked if {D.he} had any pills. {D.He} said yes, quoted a price of twenty dollars each, and handed over three tablets in exchange for three marked twenties.\""), .direct("What did the pills turn out to be?", "\"Oxycodone, according to the lab. They were stamped with the manufacturer's markings and matched what's prescribed for pain.\""), .direct("What did your team do after the buy?", "\"I left the area and signaled my team. Within ten minutes they detained {DL} a block away and found the marked bills in a pocket.\""), .cross("{D} says the pills belonged to a friend, doesn't {D.he}?", "\"Yes. But {DL} could not give a name or location for the friend.\""), .cross("{D} said the price was at cost, didn't {D.he}?", "\"{DL} said $20 each was what the friend paid. I cannot verify that.\""), .cross("Did the defendant know what the pills were?", "\"{DL} called them pain pills. I do not know the level of {DL}'s knowledge.\""), .cross("Did the defendant say how many pills {D.he} had, or offer more?", "\"No. {D.He} only sold three and didn't try to sell me more, which I noted in my report.\""), .cross("Did you hear the defendant say where the pills came from?", "\"{DL} said they were a friend's and that {D.he} was selling them at cost. I wrote that down at the time.\"")],
        theory: ("{D} sold oxycodone.", "A friend's pills."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had 14 more pills in a sock.", "The friend was never found."),
        defendant: [.direct("Did you sell those pills?", "\"I handed them over for a friend. I was just passing them along at what they cost, and I did not make anything.\""), .direct("Do you know what the pills were?", "\"Pain pills. I did not know the exact name or how strong they were.\""), .direct("Where did the extra pills come from?", "\"They were my friend's too. I was holding them for the same reason.\""), .direct("What can you tell us about the friend?", "\"A friend who has back problems had a bottle of pills and asked me to help sell some to cover rent. I said I would, and I didn't ask many questions.\""), .direct("What did you tell the buyer?", "\"That they were pain pills and the price was twenty each. I didn't know the name or the strength.\""), .direct("What were you doing with the sock?", "\"I was keeping the rest of the friend's pills in it so they wouldn't get lost. I put them in my shoe when I left the house.\""), .cross("You took $60 from a stranger on a corner, didn't you?", "\"I took the money for the friend. I did not think the buyer was a stranger worth worrying about.\""), .cross("Fourteen more pills in a sock. Is that how you hold a friend's pills?", "\"I know it looks bad. I was told to keep them out of sight, so I did.\""), .cross("Who is the friend?", "\"I do not have a full name. I know that is a problem, and It sounds bad, I know.\""), .cross("Selling pills on a street corner. Isn't that a drug sale?", "\"It looks bad, I know. I wasn't thinking about the law, and I was trying to help my friend.\""), .cross("You can't name your friend or tell where the friend is. Isn't that convenient?", "\"I can't. We lost touch after this, and I didn't think I needed to write anything down.\"")],
        openings: ("An undercover officer bought three oxycodone pills for $60 from {D} on a street corner. Minutes later, marked bills were found in {D}'s pocket, along with more pills.", "The defense will present evidence that {D} was passing along a friend's pills at what they cost and did not know what they were. The money was never {D}'s profit."),
        closings: ("Three pills, $60, marked bills in {D}'s pocket, and fourteen more pills hidden in a sock. That is a sale, and it was not a favor.", "A friend's pills, passed along at cost, and a person who did not know what they were. The State has not shown {D} knowingly sold a controlled substance for profit."),
        timeline: [(0, "4 p.m.: the undercover buy."), (0, "4:10 p.m.: officers detain {DL}."), (0, "4:20 p.m.: marked bills are found.")],
        identified: "An undercover recording.",
        aggravating: ["The offense involved sale or delivery"],
        mood: .wantsConviction)

    static let parkingKnifeIntent = SmallCases.make(
        key: "story.parkingKnifeIntent",
        category: .violent,
        headlines: ["Man Stabbed Outside Nightclub, Surgeons Save His Life", "Surveillance Video Captures Knife Thrust"],
        law: "awdwikisi",
        threshold: 8,
        spec: "Assaulted {V} with a deadly weapon, a knife, with intent to kill, inflicting serious injury, on {DATE}.",
        ages: 21...45,
        victim: true,
        summary: "{V} was stabbed twice in the abdomen outside a nightclub at 2:10 a.m. on {DATE} and survived after surgery. Surveillance video showed {D} thrust a knife and run. {DL} says {V} lunged first with a bottle.",
        state: [E(.video, 3, "Surveillance Video", "{D} thrusts a knife twice and runs."), E(.forensic, 3, "Medical Records", "Two stab wounds, one to the liver."), E(.physical, 2, "Knife", "A knife found in a dumpster with {D}'s print.", .search)],
        defense: [E(.statement, 1, "Bottle", "{DL} says {V} lunged with a bottle.")],
        role: "Police detective",
        exam: [.direct("What does the surveillance video show?", "\"At 2:10 a.m., {D} thrusts a knife twice at {V} outside the nightclub and then runs. The whole thing takes only a few seconds.\""), .direct("What were {V}'s injuries?", "\"Two stab wounds to the abdomen, one of them to the liver. {V} needed surgery and survived.\""), .direct("Where is {D} on the video afterward?", "\"Running away from the lot. {D.He} did not stay, and {D.he} did not call for help.\""), .direct("How did you reach the defendant?", "\"A tip from someone who recognized {DL} from the club's video, and a nightclub employee who knew {DL} by name. We found {DL} two days later at a relative's house.\""), .direct("What did {V} tell you in the hospital?", "\"{V} said an argument started outside the club and {DL} pulled a knife and stabbed {V.him} twice. {V} had just come out of surgery and was in pain.\""), .direct("What does the medical record say about the wounds?", "\"Two stab wounds to the abdomen, one of which cut the liver. Surgeons repaired it and {V} spent a week in the hospital.\""), .cross("Is there a bottle in the video?", "\"One is visible near {V}. It is not clear whether it was raised or on the ground.\""), .cross("Did {V} lunge at the defendant?", "\"Perhaps. The video shows movement toward {DL}, but the angle does not settle it.\""), .cross("Did you recover the knife?", "\"Not at first. {D.He} gave it up later and said it was a work knife. I can't say it was the weapon used, only that it fit the wounds.\""), .cross("Can you tell from the video whether {V} had anything in hand?", "\"There's a bottle near {V} in one frame, but the camera angle doesn't show whether {V} was holding it at the moment of the thrust.\""), .cross("Did the defendant say anything to you about why it happened?", "\"{DL} said {V} came at {DL} with a bottle first. I wrote that statement down, and a second camera angle was later pulled to check it.\""), .cross("How far apart were the defendant and {V} when the knife was used?", "\"Within arm's length. The video shows them very close together, and it is hard to tell who closed the distance.\"")],
        defenseRole: "Defendant's cousin",
        defenseExam: [.direct("What did you see at the club?", "\"I saw {V} come at {D} fast. It happened in a couple of seconds, and I was close enough to see it.\""), .direct("What did you see in {V}'s hands?", "\"Something. It might have been a bottle. I cannot say for certain what it was.\""), .direct("How did {D} react?", "\"{D.He} looked scared and backed up. Then it was over, and {D.he} ran.\""), .direct("How do you know the defendant?", "\"I'm {D.his} cousin. We're close and I was at the club with {D.him} that night.\""), .direct("What did you see in the minutes before the stabbing?", "\"I saw {DF} arguing with someone outside, and I stepped away to get a drink. When I looked back it was already happening.\""), .direct("What did you do afterward?", "\"I went looking for {DF}, and found {DF} shaking in the parking lot. We left together and I drove.\""), .cross("Did you see a bottle clearly?", "\"Maybe. It was dark, and my eyes were on {V}'s face.\""), .cross("Are you and the defendant related?", "\"Yes. We are cousins, and I know that matters. I am telling you what I saw.\""), .cross("Did you see the stabbing itself?", "\"I saw the movement. I did not see exactly where the blade went.\""), .cross("You were not watching when the knife was used?", "\"I saw {V} move toward {DF} first, but I don't know exactly when the knife came out.\""), .cross("Did the defendant say anything about the argument afterward?", "\"{D.He} said {V} came at {D.him}. I can only repeat what I was told.\"")],
        theory: ("{D} tried to kill {V}.", "A defense against a bottle."),
        allocution: "\"I'm sorry for the pain I caused.\"",
        truths: ("{DL} had texted 'I'm going to end this' that evening.", "A second camera showed {V} raising a broken bottle toward {DL}."),
        defendant: [.direct("Did you stab {V}?", "\"Yes, I did, but in defense. {V} came at me with a bottle, and I was afraid for my life.\""), .direct("Why twice?", "\"It was fast, and I was afraid. I did not stop to count. I only wanted {V} to stop.\""), .direct("Why did you have a knife?", "\"It is a work knife that I carry for my job. I did not bring it to the club to hurt anyone.\""), .direct("Tell the jury how the night began.", "\"I was at the club with some friends celebrating a birthday. {V} and I had an argument over something small near the entrance.\""), .direct("What did you see {V} do?", "\"{V} came at me with something in hand, which I thought was a bottle. I felt a rush and then I had the knife out.\""), .direct("What did you do after?", "\"I ran. I went to a relative's house and stayed there. I regret leaving and I regret what happened.\""), .cross("You ran after stabbing {V}. Why?", "\"I panicked. I was afraid of what I had done, and I did not know what to do.\""), .cross("You texted that evening about ending things. What did you mean?", "\"It was a figure of speech. I was frustrated with a situation, and I did not mean what it sounds like.\""), .cross("Two stab wounds, one to the liver. Is that proportionate?", "\"I did not think about that. I was afraid, and it was over in seconds.\""), .cross("Two stab wounds, one to the liver. How do you call that defense?", "\"I wasn't trying to hurt {V.him} badly. It happened fast and I felt I was in danger.\""), .cross("You texted earlier that evening that you wanted to end things. What did that mean?", "\"I meant a relationship, not a person. I was talking about something else entirely.\"")],
        openings: ("At 2:10 a.m. outside a nightclub, {V} was stabbed twice in the abdomen and survived after surgery. Surveillance video shows {D} thrusting a knife and running away.", "{D} admits using the knife but acted in fear after {V} lunged with a bottle. The defense will show a split-second decision made under threat."),
        closings: ("Two thrusts, a liver wound, and a person running away. The video shows who held the knife, and a bottle in the picture does not explain two stabs.", "A bottle, a lunge, and two seconds to decide. {D} did what a frightened person does. The law gives you the right to defend yourself, and that is what {D} did."),
        timeline: [(0, "1:50 a.m.: an argument outside the club."), (0, "2:10 a.m.: the stabbing."), (0, "2:12 a.m.: {DL} runs."), (0, "2:40 a.m.: {V} reaches the hospital.")],
        identified: "Surveillance video.",
        aggravating: ["The defendant was armed with a deadly weapon at the time of the crime"],
        mood: .wantsConviction,
        impact: "Another inch and I would be dead.",
        doctrines: ["selfDefense", "imperfectSelfDefense"],
        genders: ["V": .male])

    static let vanCocaine = SmallCases.make(
        key: "story.vanCocaine",
        category: .drugs,
        headlines: ["Cargo Van Stopped With Two Kilos of Cocaine Behind Panel", "Dog Alerts at Weigh Station"],
        law: "traffickingCocaine",
        threshold: 8,
        spec: "Trafficked in cocaine by transporting more than 400 grams, on {DATE}.",
        ages: 24...55,
        victim: false,
        summary: "A trooper stopped a cargo van at a weigh station on {DATE}. A dog alerted and two kilos of cocaine were found behind a side panel. {D}, the driver, says the van was a rental and the panel had been tampered with before {D.he} rented it.",
        state: [E(.physical, 3, "Cocaine", "Two kilos behind a side panel.", .search), E(.document, 2, "Rental Agreement", "{D} rented the van three days earlier.")],
        defense: [E(.statement, 1, "Rental", "{DL} says the panel was tampered with before the rental.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What did you find in the van?", "\"Two kilos of cocaine hidden behind a side panel, after a drug dog alerted at the weigh station.\""), .direct("Who rented the van?", "\"{D}, who was driving it. The rental agreement had {D.his} name on it.\""), .direct("How long had {D} had the van?", "\"Three days. {D.He} rented it three days earlier, according to the rental paperwork.\""), .direct("Why was the van stopped at the weigh station?", "\"It was a routine inspection of commercial vehicles. The van was marked as a cargo vehicle and the driver pulled into the lane without any issue.\""), .direct("How did you decide to search?", "\"A dog alerted at the side of the van. I asked {D.him} for consent, and {D.he} said to go ahead and that nothing was inside.\""), .direct("What did you find behind the panel?", "\"Two kilos of cocaine in plastic-wrapped bricks. The panel screws had fresh tool marks and some were not the same type as the others.\""), .cross("Other people had rented that van before, hadn't they?", "\"Possibly. I do not have the full rental history, and I did not examine who rented it before.\""), .cross("What did you notice about the panel?", "\"The screws showed tool marks. I cannot say when the panel was last opened.\""), .cross("Did the defendant seem surprised?", "\"{D.He} said {D.he} did not know. I cannot read minds, and I only report what was said.\""), .cross("Did the defendant seem nervous or try to leave?", "\"No. {D.He} was calm, cooperative, and gave me the rental agreement without being asked.\""), .cross("Did you find any other contraband or cash in the van?", "\"No. The cargo was ordinary boxes, and I found no scale, no cash, and nothing else that suggested distribution.\"")],
        defenseRole: "Rental company clerk",
        defenseExam: [.direct("Do you inspect vans before they are rented?", "\"Yes. We do a walkaround and check the lights, the tires, and the cargo area. It is routine.\""), .direct("Did you inspect this van?", "\"Yes, before the rental to {D}. It looked normal, and I did not notice anything unusual.\""), .direct("Did you look behind the side panel?", "\"No. We do not remove panels. We only check what we can see.\""), .direct("What is your job at the rental company?", "\"I'm a counter clerk and I handle check-in and check-out. I've worked there six years.\""), .direct("How is a van checked when it comes back?", "\"A staff member walks around it, checks fuel, mileage, and visible damage, and signs the return form. We don't remove panels.\""), .direct("How many people had rented this van in the month before {D}?", "\"Five, I believe, over about three weeks. I can look at the rental log for the exact number.\""), .cross("Who last worked on that panel?", "\"Our mechanic may have. I do not know, and the records are not complete.\""), .cross("Could someone have tampered with it before the rental?", "\"I suppose it could have happened. I cannot rule it out.\""), .cross("Did the defendant ask to open any panels?", "\"No. {D.He} did not ask for anything unusual.\""), .cross("Did you personally check this van before the rental to the defendant?", "\"I looked at it and it seemed normal. I didn't open any panels.\""), .cross("Could the panel have been opened by someone before the defendant rented it?", "\"It's possible. We don't inspect behind panels, and a van is sometimes left unattended in our lot.\"")],
        theory: ("{D} carried two kilos of cocaine.", "A rental with a tampered panel."),
        allocution: "\"I knew what was there.\"",
        truths: ("The panel's screws had fresh tool marks.", "The rental agency's own mechanic replaced that panel the week before without logging it."),
        defendant: [.direct("Did you know the cocaine was in the van?", "\"No. I had no idea. If I had known, I would never have driven it through a weigh station.\""), .direct("Why did you rent the van?", "\"I had a job hauling cargo, and I needed a van for a few days. It was a normal rental.\""), .direct("Did you inspect the panels?", "\"No. I looked at the cargo area and nothing else. I had no reason to open a panel.\""), .direct("Describe your job and why you needed a van for the jury.", "\"I haul small freight on weekends for a few clients. I don't own a van, so I rented one from a local agency for three days.\""), .direct("What did you do with the van during those three days?", "\"I picked up two loads of boxes and drove them to a warehouse. The panel on the side was never opened and I never needed it.\""), .direct("What did you think when the trooper told you what was found?", "\"I was in shock. I told the trooper I had no idea and asked to call the rental agency.\""), .cross("Fresh tool marks were on the panel screws, weren't they?", "\"I did not see them. I did not look. I know it is not a good answer.\""), .cross("You carried a second phone, didn't you?", "\"Yes, for work. It was a work phone, and it had nothing to do with this.\""), .cross("Two kilos is worth a lot of money. Why would you rent a van and risk that?", "\"I would not. I did not know it was there, and I did not do anything to put it there.\""), .cross("You drove the van for three days and never noticed tool marks?", "\"I never looked at the panel. I checked the lights and tires and nothing else.\""), .cross("You have a second phone in the van. Why?", "\"It's a work phone for deliveries. It's got customer numbers and delivery confirmations.\"")],
        openings: ("A trooper stopped a cargo van at a weigh station, and a drug dog alerted. Behind a side panel were two kilos of cocaine, and the driver and renter was {D}.", "{D} rented a van for a job and never touched the panel. The defense will show that the panel had been tampered with before {D} took the keys."),
        closings: ("Two kilos behind a panel, in a van rented to {D} for three days. The driver is responsible for what is in the vehicle, and {D} was the driver.", "The panel was opened before {D} ever rented the van, and no one has shown that {D} knew what was behind it. A name on a rental form is not knowledge."),
        timeline: [(-3, "{DL} rents the van."), (0, "7 a.m.: a dog alerts."), (0, "7:40 a.m.: the panel is opened.")],
        identified: "A weigh station search.",
        aggravating: [],
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "burdenOfProof"])

    static let firefighterBurned = SmallCases.make(
        key: "story.firefighterBurned",
        category: .property,
