        state: [E(.forensic, 3, "Fire Marshal", "Gasoline trail at the back door."), E(.video, 2, "Neighbor Camera", "A figure at the back door at 2:30 a.m."), E(.document, 2, "Eviction Order", "Evicted two days earlier.")],
