    static let scaldChildAbuse = SmallCases.make(
        key: "story.scaldChildAbuse",
        category: .family,
        headlines: ["Toddler Scalded in Bath, Hospital Reports Possible Abuse", "Burn Pattern Does Not Match Parent's Account"],
