        spec: "Intentionally inflicted serious bodily injury upon {V}, a child under sixteen, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "A toddler, {V}, was brought to an emergency room on {DATE} with burns on both legs and buttocks. {D}, the caregiver, said the child climbed into a hot bath alone. A burn specialist found a pattern of immersion. {DL} says the water heater was set too high.",
        state: [E(.forensic, 3, "Burn Specialist", "Immersion pattern inconsistent with climbing in."), E(.document, 2, "Water Heater Report", "Water at 150 degrees.")],
        defense: [E(.statement, 1, "Heater", "{DL} says the heater was set too high.")],
        role: "Emergency physician",
        exam: [.direct("What did you find when the child arrived?", "\"Burns on both legs and buttocks. The pattern showed the skin was held in hot water, not splashed.\""), .direct("What does an immersion burn look like?", "\"It has clear lines where the water level stopped, and the burns are even and symmetric. Splashes leave scattered marks.\""), .direct("What did {D} tell you?", "\"{D} said the child climbed into a hot bath alone. That is what was reported to me at the hospital.\""), .direct("What is your specialty, and what happened when the child arrived?", "\"I'm an emergency physician. The child arrived at about nine in the evening with burns across both legs and the buttocks, crying and in obvious pain.\""), .direct("What features of the burns concerned you?", "\"Sharp lines at the upper thigh and a pattern on the buttocks without splash marks. That distribution is typical of being held in hot water rather than splashed.\""), .direct("What treatment did the child receive?", "\"We cooled and dressed the burns, started pain control and fluids, and transferred the child to a burn unit. The child recovered but will have scars.\""), .cross("The water heater was set very high, wasn't it?", "\"I was told about 150 degrees, which is hot enough to burn in seconds.\""), .cross("Can a child that age climb into a bath alone?", "\"Yes, a three-year-old can climb in. It is possible.\""), .cross("Can you say who put the child in the water?", "\"No. I can only describe the injuries. I cannot say who did it.\""), .cross("Isn't it possible a three-year-old could climb into a hot bath and sit down?", "\"A child can climb in, but then the burn would likely be on the feet and legs in a splash pattern. The pattern I saw is different.\""), .cross("Did you consider that the water heater may have been set too hot?", "\"Yes. Water at 150 degrees can cause a severe burn in a couple of seconds, so I understand the importance of that fact.\"")],
        defenseRole: "Home inspector",
        defenseExam: [.direct("What was the water heater set to?", "\"Too high. It was set to around 150, which is above the recommended safe setting.\""), .direct("What could that do?", "\"It can cause severe burns within seconds, especially to a child.\""), .direct("Whose job is it to set the heater?", "\"The landlord or the owner. It is not usually something a tenant changes.\""), .direct("What is your profession, and why did you inspect the home?", "\"I'm a licensed home inspector. I was asked to examine the water heater and test the temperature at the tap.\""), .direct("What did your measurements show?", "\"Water at the bathroom tap came out at about 150 degrees. The heater's dial was turned to its highest setting.\""), .direct("What does the standard recommend?", "\"A maximum of 120 degrees, which is the common safe setting. At 150, a child can be seriously burned in two seconds.\""), .cross("Is that dangerous?", "\"Yes. At that temperature, a child can be burned in a few seconds.\""), .cross("Could a bath at that temperature be unnoticed by an adult?", "\"It might feel very hot to an adult, but not always until too late.\""), .cross("Did you check the home before this incident?", "\"No. I inspected after the report.\""), .cross("Can you say who set the dial or when?", "\"No. The dial was at maximum when I inspected, but I can't say when it was set or by whom.\""), .cross("Does a hot water heater explain the immersion pattern the doctor described?", "\"I'm not qualified to say. I can only tell you how hot the water was.\"")],
        theory: ("{D} hurt a child.", "A hot water heater."),
        allocution: "\"I'm so sorry.\"",
        truths: ("{DL} waited three hours before seeking care.", "A text said 'the water was fine' two minutes before."),
